-- How-to demos for the exercise library. Animated GIFs and instructions come from the free
-- ExerciseDB API (oss.exercisedb.dev, gifs at static.exercisedb.dev/media/<gif_id>.gif).
-- Exercises it has no GIF for fall back to two photos (start and end of the movement)
-- from free-exercise-db (github.com/yuhonas/free-exercise-db, public domain).

alter table public.exercises
  add column gif_id text,
  add column media_id text,
  add column instructions text[] not null default '{}';

update public.exercises set gif_id = 'EIeI8Vf', media_id = 'Barbell_Bench_Press_-_Medium_Grip', instructions = array['Settle onto a bench with your feet planted and your back pressed against the bench.', 'Hold the barbell with palms facing down just beyond shoulder width.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]
  where created_by is null and name = 'Bench Press (Barbell)';
update public.exercises set gif_id = '3TZduzM', media_id = 'Barbell_Incline_Bench_Press_-_Medium_Grip', instructions = array['Angle the bench to roughly 45 degrees.', 'Get onto the bench with your feet planted.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]
  where created_by is null and name = 'Incline Bench Press (Barbell)';
update public.exercises set gif_id = 'SpYC0Kp', media_id = 'Dumbbell_Bench_Press', instructions = array['Settle onto a bench with your feet planted and your back pressed against the bench.', 'Take a dumbbell in each hand, with your palms facing forward and your arms extended above your chest.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]
  where created_by is null and name = 'Bench Press (Dumbbell)';
update public.exercises set gif_id = 'B3Rxp6L', media_id = 'Incline_Dumbbell_Press', instructions = array['Angle the bench to roughly 45 degrees.', 'Take a seat on the bench with your back against the pad and feet planted.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]
  where created_by is null and name = 'Incline Bench Press (Dumbbell)';
update public.exercises set gif_id = 'yz9nUhF', media_id = 'Dumbbell_Flyes', instructions = array['Settle onto a bench with a dumbbell in each hand, palms facing each other.', 'Reach your arms straight up over your chest, with a slight bend in your elbows.', 'Keep a soft elbow bend and set the shoulders before moving the arms.', 'With a soft bend in the elbows, sweep your arms together in a wide arc.', 'Keep the elbow angle nearly unchanged through the arc.', 'Open the arms back along the same arc without dropping the load.']::text[]
  where created_by is null and name = 'Chest Fly (Dumbbell)';
update public.exercises set gif_id = '0CXGHya', media_id = 'Cable_Crossover', instructions = array['Set the cable pulleys to chest height.', 'Take your place in the center of the cable machine with one foot in front of the other.', 'Keep a soft elbow bend and set the shoulders before moving the arms.', 'Bring the handles across the front of your chest in a broad arc, keeping a slight elbow bend.', 'Keep the elbow angle nearly unchanged through the arc.', 'Open the arms back along the same arc without dropping the load.']::text[]
  where created_by is null and name = 'Cable Crossover';
update public.exercises set gif_id = 'v3xmPAR', media_id = 'Butterfly', instructions = array['Fit the seat to your body, then settle into the machine.', 'Hold the handles with a pronated grip and keep your elbows soft.', 'Keep a soft elbow bend and set the shoulders before moving the arms.', 'With a soft bend in the elbows, sweep your arms together in a wide arc.', 'Keep the elbow angle nearly unchanged through the arc.', 'Open the arms back along the same arc without dropping the load.']::text[]
  where created_by is null and name = 'Pec Deck';
update public.exercises set gif_id = 'DOoWcnA', media_id = 'Machine_Bench_Press', instructions = array['Fit the seat to your body, then settle into the machine.', 'Hold the handles with palms facing down and position your elbows at a 90-degree angle.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]
  where created_by is null and name = 'Chest Press (Machine)';
update public.exercises set gif_id = 'I4hDWkc', media_id = 'Pushups', instructions = array['Begin in a high plank position with your hands just beyond shoulder width and your feet together.', 'Brace your trunk and lower your body toward the ground by bending your elbows, keeping your body in a straight line.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]
  where created_by is null and name = 'Push Up';
update public.exercises set gif_id = '9WTm7dq', media_id = 'Dips_-_Chest_Version', instructions = array['Set yourself on parallel bars with your arms straight and your body straight.', 'Before moving, lower your body by bending your elbows until your shoulders are below your elbows.', 'Set the shoulders down and keep the elbows pointed mostly behind you.', 'Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.', 'Choose a depth that lets the shoulders stay comfortable.', 'Press through the hands to rise, then reset the shoulders before another rep.']::text[]
  where created_by is null and name = 'Chest Dip';
update public.exercises set gif_id = 'ila4NZS', media_id = 'Barbell_Deadlift', instructions = array['Stand and set your feet about shoulder width and the barbell on the ground in front of you.', 'Bend your knees and hinge at the hips to lower your torso and grip the barbell with palms facing down, hands just beyond shoulder width.', 'Unlock the knees and brace the abdomen before moving the hips back.', 'Push the hips back while keeping the load close and the spine steady.', 'Keep the weight close to the legs and stop when the back would begin to round.', 'Drive the hips forward to stand tall without leaning back at the top.']::text[]
  where created_by is null and name = 'Deadlift (Barbell)';
update public.exercises set gif_id = 'eZyBC3j', media_id = 'Bent_Over_Barbell_Row', instructions = array['Stand and set your feet about shoulder width and knees soft.', 'Bend forward at the hips while with your spine steady and chest up.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]
  where created_by is null and name = 'Bent Over Row (Barbell)';
update public.exercises set gif_id = 'C0MA9bC', media_id = 'One-Arm_Dumbbell_Row', instructions = array['Stand and set your feet about shoulder width, holding a dumbbell in one hand with your palm facing your body.', 'Bend your knees slightly and hinge forward at the hips, with your spine steady and your core engaged.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Keep both shoulders level and resist turning toward the working arm.', 'Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it.']::text[]
  where created_by is null and name = 'Single Arm Row (Dumbbell)';
update public.exercises set gif_id = 'LEprlgG', media_id = 'Wide-Grip_Lat_Pulldown', instructions = array['Take a seat on the lat pulldown machine with your knees positioned under the pads.', 'Hold the cable bar with palms facing down, just beyond shoulder width.', 'Sit tall and set the shoulders before drawing the handle down.', 'Pull the handle down by driving your elbows toward your ribs; keep your torso steady.', 'Pull with the elbows rather than leaning far back to move the handle.', 'Let the handle rise steadily until the arms are long, then reset the shoulders.']::text[]
  where created_by is null and name = 'Lat Pulldown (Cable)';
update public.exercises set gif_id = 'fUBheHs', media_id = 'Seated_Cable_Rows', instructions = array['Take a seat on the cable row machine with your feet flat on the footrests and your knees soft.', 'Hold the handles with palms facing down, with your spine steady and your shoulders relaxed.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]
  where created_by is null and name = 'Seated Cable Row';
update public.exercises set gif_id = 'aaXr7ld', media_id = 'T-Bar_Row_with_Handle', instructions = array['Set the seat height and footplate position to ensure proper alignment.', 'Take a seat on the machine with your chest against the pad and your feet flat on the footplate.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]
  where created_by is null and name = 'T-Bar Row';
update public.exercises set gif_id = 'lBDjFxJ', media_id = 'Pullups', instructions = array['Suspend yourself from a pull-up bar with your palms turned away from you and your arms straight.', 'Brace your trunk and draw your shoulder blades toward each other.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]
  where created_by is null and name = 'Pull Up';
update public.exercises set gif_id = 'T2mxWqc', media_id = 'Chin-Up', instructions = array['Suspend yourself from a pull-up bar with your palms facing toward you and your hands about shoulder width.', 'Brace your trunk and pull your body up toward the bar, leading with your chest.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]
  where created_by is null and name = 'Chin Up';
update public.exercises set gif_id = 'x69MAlq', media_id = 'Straight-Arm_Pulldown', instructions = array['Connect a straight bar to the high pulley of a cable machine.', 'Face the machine from a stable stance with feet about shoulder width.', 'Sit tall and set the shoulders before drawing the handle down.', 'Pull the handle down by driving your elbows toward your ribs; keep your torso steady.', 'Pull with the elbows rather than leaning far back to move the handle.', 'Let the handle rise steadily until the arms are long, then reset the shoulders.']::text[]
  where created_by is null and name = 'Straight Arm Pulldown';
update public.exercises set gif_id = 'zhMwOwE', media_id = 'Hyperextensions_Back_Extensions', instructions = array['Set the hyperextension bench so that your upper thighs are resting on the pad and your feet are secured.', 'Fold your arms over your chest or place your hands behind your head.', 'Secure the hips and feet on the support before lifting.', 'Raise your torso or legs until they line up with your body, without arching sharply at the lower back.', 'Finish in a straight body line, before the lower back overarches.', 'Bring the weight or body back to its starting position without rushing.']::text[]
  where created_by is null and name = 'Back Extension';
update public.exercises set gif_id = 'wdRZISl', media_id = 'Barbell_Shoulder_Press', instructions = array['Stand and set your feet about shoulder width and hold the barbell with palms facing down, hands slightly closer than about shoulder width.', 'Before moving, lift the barbell to shoulder height, keeping your elbows close to your body.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]
  where created_by is null and name = 'Overhead Press (Barbell)';
update public.exercises set gif_id = 'znQUdHY', media_id = 'Dumbbell_Shoulder_Press', instructions = array['Take a seat on a bench with a dumbbell in each hand, resting on your thighs.', 'Before moving, raise the dumbbells to shoulder height, palms facing forward.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]
  where created_by is null and name = 'Shoulder Press (Dumbbell)';
update public.exercises set gif_id = 'DsgkuIt', media_id = 'Side_Lateral_Raise', instructions = array['Stand and set your feet about shoulder width and hold a dumbbell in each hand, palms facing your body.', 'Keep your spine in a comfortable neutral position and Brace your trunk.', 'Start with a manageable load and a small bend in the elbows.', 'Raise the arms out to the sides to about shoulder height without leaning or shrugging.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]
  where created_by is null and name = 'Lateral Raise (Dumbbell)';
update public.exercises set gif_id = 'goJ6ezq', media_id = 'Cable_Seated_Lateral_Raise', instructions = array['Stand and set your feet about shoulder width and Hold the cable handles with palms facing down.', 'Maintain straight arms and your core engaged.', 'Start with a manageable load and a small bend in the elbows.', 'Raise the arms out to the sides to about shoulder height without leaning or shrugging.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]
  where created_by is null and name = 'Lateral Raise (Cable)';
update public.exercises set gif_id = '8DiFDVA', media_id = 'Seated_Bent-Over_Rear_Delt_Raise', instructions = array['Stand and set your feet about shoulder width and hold a dumbbell in each hand.', 'Bend your knees slightly and hinge forward at the hips, with your spine steady.', 'Keep a soft elbow bend and set the shoulders before moving the arms.', 'With a soft bend in the elbows, sweep your arms together in a wide arc.', 'Keep the elbow angle nearly unchanged through the arc.', 'Open the arms back along the same arc without dropping the load.']::text[]
  where created_by is null and name = 'Rear Delt Fly (Dumbbell)';
update public.exercises set gif_id = 'wqNPGCg', media_id = 'Face_Pull', instructions = array['Connect a rope handle to a low pulley cable machine.', 'Face the machine from a stable stance with feet about shoulder width.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]
  where created_by is null and name = 'Face Pull';
update public.exercises set gif_id = 'NJzBsGJ', media_id = 'Dumbbell_Shrug', instructions = array['Stand and set your feet about shoulder width and hold a dumbbell in each hand with your palms facing your body.', 'Maintain straight arms and let the dumbbells hang by your sides.', 'Let the arms hang long and keep the head neutral.', 'Lift your shoulders toward your ears without bending the elbows or rolling the shoulders.', 'Lift and lower vertically without circling the shoulders.', 'Bring the weight or body back to its starting position without rushing.']::text[]
  where created_by is null and name = 'Shrug (Dumbbell)';
update public.exercises set gif_id = '25GPyDY', media_id = 'Barbell_Curl', instructions = array['Stand tall with your feet about shoulder width and hold a barbell with palms facing up, palms facing forward.', 'Hold your elbows near your torso and Breathe out and curl the weights while contracting your biceps.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]
  where created_by is null and name = 'Bicep Curl (Barbell)';
update public.exercises set gif_id = '3s4NnTh', media_id = 'Dumbbell_Bicep_Curl', instructions = array['Stand tall with a dumbbell in each hand, palms facing forward and arms straight.', 'With your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]
  where created_by is null and name = 'Bicep Curl (Dumbbell)';
update public.exercises set gif_id = '2NpxjC1', media_id = 'Alternate_Hammer_Curl', instructions = array['Stand tall with a dumbbell in each hand, palms facing your torso.', 'Hold your elbows near your torso and rotate the palms of your hands until they are facing forward.', 'Set the shoulders and upper arms before bending the elbows.', 'Curl with palms facing each other and elbows near your sides; avoid rocking back.', 'Keep the palms facing each other and the wrists straight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]
  where created_by is null and name = 'Hammer Curl (Dumbbell)';
update public.exercises set gif_id = 'hacCyUv', media_id = 'Preacher_Curl', instructions = array['Take a seat on a preacher curl bench and place your upper arms on the pad, gripping the ez barbell with palms facing up.', 'Set your triceps on the pad and straighten your arms, with your spine steady.', 'Set the working upper arm against the preacher pad and leave the elbow free to bend.', 'Curl the weight while your upper arms stay in contact with the pad.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]
  where created_by is null and name = 'Preacher Curl (EZ Bar)';
update public.exercises set gif_id = 'G08RZcQ', media_id = 'Standing_Biceps_Cable_Curl', instructions = array['Face the cable machine from a stable stance with feet about shoulder width.', 'Hold the cable attachment with palms facing up.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]
  where created_by is null and name = 'Cable Curl';
update public.exercises set gif_id = 'dU605di', media_id = 'Triceps_Pushdown_-_Rope_Attachment', instructions = array['Connect a rope attachment to a high pulley on a cable machine.', 'Face the machine with your feet about shoulder width and a slight bend in your knees.', 'Stand far enough from the stack for the cable to stay taut.', 'Keep your elbows near your ribs and straighten your arms against the cable.', 'Keep the elbows close to the body instead of letting the shoulders swing.', 'Ease back to the start before repeating.']::text[]
  where created_by is null and name = 'Triceps Pushdown (Rope)';
update public.exercises set gif_id = 'h8LFzo9', media_id = 'EZ-Bar_Skullcrusher', instructions = array['Settle onto a bench with your feet planted and your head at the end of the bench.', 'Take hold of the barbell with palms facing down, hands about shoulder width, and extend your arms straight up over your chest.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]
  where created_by is null and name = 'Skull Crusher (EZ Bar)';
update public.exercises set gif_id = 'PdmaD0N', media_id = 'Standing_Dumbbell_Triceps_Extension', instructions = array['Stand and set your feet about shoulder width and hold a dumbbell in one hand.', 'Before moving, raise the dumbbell overhead, keeping your arm straight.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]
  where created_by is null and name = 'Overhead Triceps Extension';
update public.exercises set gif_id = 'J6Dx1Mu', media_id = 'Close-Grip_Barbell_Bench_Press', instructions = array['Settle onto a bench with your feet planted and your back pressed against the bench.', 'Hold the barbell with a close grip, slightly narrower than about shoulder width.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]
  where created_by is null and name = 'Close Grip Bench Press';
update public.exercises set gif_id = 'X6C6i5Y', media_id = 'Dips_-_Triceps_Version', instructions = array['Take a seat on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.', 'Move your butt off the bench, supporting your weight with your hands.', 'Set the shoulders down and keep the elbows pointed mostly behind you.', 'Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.', 'Choose a depth that lets the shoulders stay comfortable.', 'Press through the hands to rise, then reset the shoulders before another rep.']::text[]
  where created_by is null and name = 'Triceps Dip';
update public.exercises set gif_id = '2dImyQ8', media_id = 'Seated_Dumbbell_Palms-Up_Wrist_Curl', instructions = array['Plant both feet while seated on a bench; hold a dumbbell in each hand, palms facing up.', 'Set your forearms on your thighs, letting your wrists hang off the edge.', 'Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Move through the wrists or fingers while the forearms stay supported and still.', 'Use a small, smooth range without swinging the elbows.', 'Ease back to the start without letting the load fall from your hands.']::text[]
  where created_by is null and name = 'Wrist Curl (Dumbbell)';
update public.exercises set gif_id = 'qXTaZnJ', media_id = 'Barbell_Squat', instructions = array['Stand and set your feet about shoulder width, toes slightly turned out.', 'Rest the bar across the upper back and take a secure grip.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]
  where created_by is null and name = 'Squat (Barbell)';
update public.exercises set gif_id = 'zG0zs85', media_id = 'Front_Barbell_Squat', instructions = array['Begin by standing with your feet about shoulder width, toes slightly turned out.', 'Take hold of the barbell ahead of your shoulders, resting it on your collarbone and shoulders.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]
  where created_by is null and name = 'Front Squat (Barbell)';
update public.exercises set gif_id = '10Z2DXU', media_id = 'Leg_Press', instructions = array['Set the seat and footplate of the sled machine to a comfortable position.', 'Take a seat on the sled machine with your back against the backrest and your feet about shoulder width on the footplate.', 'Set your feet firmly on the plate and keep the hips against the seat.', 'Bend the knees to bring the platform toward you, then press it away through the feet.', 'Stop the descent before the hips lift from the seat.', 'Bring the weight or body back to its starting position without rushing.']::text[]
  where created_by is null and name = 'Leg Press';
update public.exercises set gif_id = 'Qa55kX1', media_id = 'Hack_Squat', instructions = array['Set the sled machine to a comfortable position for your height.', 'Stand and set your feet about shoulder width on the platform, toes slightly pointed outwards.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]
  where created_by is null and name = 'Hack Squat';
update public.exercises set gif_id = 'my33uHU', media_id = 'Leg_Extensions', instructions = array['Set the seat height and backrest of the machine to fit your body.', 'Take a seat on the machine with your back against the backrest and your feet on the footpad.', 'Set the pad just above the ankles and keep the thighs against the seat.', 'Straighten your knees to lift the pad, keeping your hips against the seat.', 'Lift without swinging and avoid snapping the knees straight.', 'Bring the weight or body back to its starting position without rushing.']::text[]
  where created_by is null and name = 'Leg Extension';
update public.exercises set gif_id = 'qx4fgX7', media_id = 'Split_Squat_with_Dumbbells', instructions = array['Stand and set your feet about shoulder width, holding a dumbbell in each hand.', 'Step forward with one foot and position your feet so that your front foot is flat on the ground and your back foot is elevated on a bench or step.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]
  where created_by is null and name = 'Bulgarian Split Squat';
update public.exercises set gif_id = 'RRWFUcw', media_id = 'Dumbbell_Lunges', instructions = array['Stand and set your feet about shoulder width, holding a dumbbell in each hand.', 'Step forward with your right foot, lowering your body into a lunge position.', 'Set your stance wide enough to balance before bending either knee.', 'Step into the movement and bend both knees, keeping your front foot planted.', 'Keep the front foot planted and avoid collapsing inward at the knee.', 'Push through the lead foot to return to the start, then change legs as planned.']::text[]
  where created_by is null and name = 'Walking Lunge (Dumbbell)';
update public.exercises set gif_id = 'yn8yg1r', media_id = 'Goblet_Squat', instructions = array['Stand and set your feet about shoulder width, holding a dumbbell vertically against your chest with both hands.', 'With your chest up and core engaged, lower your body down into a squat position by pushing your hips back and bending your knees.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]
  where created_by is null and name = 'Goblet Squat';
update public.exercises set gif_id = 'wQ2c4XD', media_id = 'Romanian_Deadlift', instructions = array['Stand and set your feet about shoulder width and your toes pointing forward.', 'Take hold of the barbell with palms facing down, hands just beyond shoulder width.', 'Unlock the knees and brace the abdomen before moving the hips back.', 'Send your hips back with a soft knee bend, lowering the load close to your legs until the hamstrings stretch.', 'Keep the weight close to the legs and stop when the back would begin to round.', 'Drive the hips forward to stand tall without leaning back at the top.']::text[]
  where created_by is null and name = 'Romanian Deadlift (Barbell)';
update public.exercises set gif_id = '17lJ1kr', media_id = 'Lying_Leg_Curls', instructions = array['Set the machine to fit your body and select the desired weight.', 'Position yourself face down on the machine with your legs straight and your heels against the padded lever.', 'Line the knees up with the machine or bench edge before starting the curl.', 'Bend your knees to draw the pad toward you without lifting your hips from the support.', 'Keep the hips still while the knees bend.', 'Ease back to the start before repeating.']::text[]
  where created_by is null and name = 'Lying Leg Curl';
update public.exercises set gif_id = 'Zg3XY7P', media_id = 'Seated_Leg_Curl', instructions = array['Set the machine to fit your body and sit on it with your back against the backrest.', 'Set your lower legs under the padded lever, just above your ankles.', 'Line the knees up with the machine or bench edge before starting the curl.', 'Bend your knees to draw the pad toward you without lifting your hips from the support.', 'Keep the hips still while the knees bend.', 'Return along the same path at a controlled pace.']::text[]
  where created_by is null and name = 'Seated Leg Curl';
update public.exercises set gif_id = 'qKBpF7I', media_id = 'Barbell_Hip_Thrust', instructions = array['Begin by lying flat on your back on the ground with your knees bent and feet planted.', 'Set a barbell across your hips, holding it securely with both hands.', 'Plant the feet and keep the ribs from flaring as the hips prepare to rise.', 'Press through the feet and lift your hips until your torso and thighs line up.', 'Stop when the hips line up with the torso; do not arch higher through the lower back.', 'Lower the hips steadily and keep the feet planted for the next lift.']::text[]
  where created_by is null and name = 'Hip Thrust (Barbell)';
update public.exercises set gif_id = 'CHpahtl', media_id = 'Thigh_Abductor', instructions = array['Set the seat height so that your knees are at a 90-degree angle.', 'Take a seat on the machine with your back against the backrest and your feet on the footrests.', 'Square the pelvis before moving the working leg.', 'Open the knees or legs against resistance without shifting your torso.', 'Move only as far as the pelvis can remain steady.', 'Bring the weight or body back to its starting position without rushing.']::text[]
  where created_by is null and name = 'Hip Abduction (Machine)';
update public.exercises set gif_id = 'ykUOVze', media_id = 'Standing_Calf_Raises', instructions = array['Set the machine to your height and stand with your feet about shoulder width.', 'Set your shoulders under the pads and hold onto the handles for stability.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Pause at the top without rolling the ankles outward.', 'Lower the heels at a measured pace before rising again.']::text[]
  where created_by is null and name = 'Standing Calf Raise';
update public.exercises set gif_id = 'bOOdeyc', media_id = 'Seated_Calf_Raise', instructions = array['Set the seat height so that your knees are soft and your feet are flat on the footplate.', 'Set your toes on the footplate with your heels hanging off the edge.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Pause at the top without rolling the ankles outward.', 'Lower the heels at a measured pace before rising again.']::text[]
  where created_by is null and name = 'Seated Calf Raise';
update public.exercises set gif_id = 'VBAWRPG', media_id = 'Plank', instructions = array['Begin by lying face down on the floor.', 'Set your forearms on the ground, with your elbows directly under your shoulders.', 'Brace the abdomen and find a position you can maintain without holding your breath.', 'Brace your midsection and hold the position while breathing normally.', 'Keep breathing steadily as you maintain the same body line.', 'Keep the shape for the planned time, then come out of it with control.']::text[]
  where created_by is null and name = 'Plank';
update public.exercises set gif_id = 'I3tsCnC', media_id = 'Hanging_Leg_Raise', instructions = array['Suspend yourself from a pull-up bar with your arms straight and your palms turned away from you.', 'Brace your trunk and lift your legs up in front of you, keeping them straight.', 'Brace the abdomen and keep the shoulders anchored to the support.', 'Lift your legs by bracing your trunk and moving at the hips rather than swinging.', 'Slow the legs before they pull the lower back out of position.', 'Lower the legs slowly without swinging or losing your trunk position.']::text[]
  where created_by is null and name = 'Hanging Leg Raise';
update public.exercises set gif_id = '8xUv4J7', media_id = 'Cable_Crunch', instructions = array['Take a seat on a cable machine with your feet planted and your knees bent.', 'Take hold of the cable handle with both hands and position it behind your head.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]
  where created_by is null and name = 'Cable Crunch';
update public.exercises set gif_id = 'TFqbd8t', media_id = 'Crunches', instructions = array['Settle onto your back with your knees bent and feet planted.', 'Set your hands behind your head with your elbows pointing outwards.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]
  where created_by is null and name = 'Crunch';
update public.exercises set gif_id = 'XVDdcoj', media_id = 'Russian_Twist', instructions = array['Take a seat on the ground with your knees bent and feet planted.', 'Lean back slightly while with your spine steady and your core engaged.', 'Set the pelvis and make the turn through the rib cage.', 'Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Keep the turn smooth instead of throwing the arms across the body.', 'Return through center before turning to the other side.']::text[]
  where created_by is null and name = 'Russian Twist';
update public.exercises set gif_id = 'NAgVB3t', media_id = 'Ab_Roller', instructions = array['Get down on the floor and place the wheel roller in front of you.', 'Set your hands on the handles of the wheel roller and extend your arms straight out in front of you.', 'Tighten the abdomen and keep the pelvis tucked before the arms reach away.', 'Reach the arms away while keeping your ribs and pelvis aligned; stop before the lower back sags.', 'Stop reaching when the lower back starts to sag.', 'Pull back to the start through your shoulders and abdominals, keeping the same body line.']::text[]
  where created_by is null and name = 'Ab Wheel Rollout';
update public.exercises set gif_id = 'rjiM4L3', media_id = 'Running_Treadmill', instructions = array['Set the incline level on the treadmill to your desired intensity.', 'Step onto the treadmill with your feet about shoulder width.', 'Stand tall with the load secure and the shoulders level.', 'Walk at a controlled pace, keeping your shoulders level and your steps even.', 'Keep steps even and avoid leaning away from the load.', 'Stop before posture breaks down, set the load down safely, and reset for the next walk.']::text[]
  where created_by is null and name = 'Treadmill Run';
update public.exercises set gif_id = 'H1PESYI', media_id = 'Bicycling_Stationary', instructions = array['Set the seat height and position to ensure proper alignment.', 'Set your feet on the pedals and secure them with the straps if available.', 'Start at a pace that lets the feet and arms move in sync.', 'Move at a repeatable pace, keeping the motion smooth and your breathing steady.', 'Keep the pattern repeatable as speed increases.', 'Keep the rhythm for the planned interval, slowing if your form starts to slip.']::text[]
  where created_by is null and name = 'Cycling (Stationary)';
update public.exercises set gif_id = null, media_id = 'Rowing_Stationary', instructions = array['To begin, seat yourself on the rower. Make sure that your heels are resting comfortably against the base of the foot pedals and that the straps are secured. Select the program that you wish to use, if applicable. Sit up straight and bend forward at the hips.', 'There are three phases of movement when using a rower. The first phase is when you come forward on the rower. Your knees are bent and against your chest. Your upper body is leaning slightly forward while still maintaining good posture. Next, push against the foot pedals and extend your legs while bringing your hands to your upper abdominal area, squeezing your shoulders back as you do so. To avoid straining your back, use primarily your leg and hip muscles.', 'The recovery phase simply involves straightening your arms, bending the knees, and bringing your body forward again as you transition back into the first phase.']::text[]
  where created_by is null and name = 'Rowing Machine';
update public.exercises set gif_id = 'e1e76I2', media_id = 'Rope_Jumping', instructions = array['Take hold of the handles of the jump rope with your hands, palms facing inward.', 'Stand and set your feet about shoulder width and knees soft.', 'Bend the hips and knees slightly to load the jump.', 'Load the legs with a small bend, then drive through the floor and land softly.', 'Land with bent hips and knees and let the feet absorb the impact.', 'Absorb the landing through the hips and knees before repeating.']::text[]
  where created_by is null and name = 'Skipping Rope';
update public.exercises set gif_id = null, media_id = 'Stairmaster', instructions = array['To begin, step onto the stairmaster and select the desired option from the menu. You can choose a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise.', 'Pump your legs up and down in an established rhythm, driving the pedals down but not all the way to the floor. It is recommended that you maintain your grip on the handles so that you don''t fall. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.', 'Stairmasters offer convenience, cardiovascular benefits, and usually have less impact than running outside. They are typically much harder than other cardio equipment. A 150 lb person will typically burn over 300 calories in 30 minutes, compared to about 175 calories walking.']::text[]
  where created_by is null and name = 'Stair Climber';
